    ["ou", "ओ"], ["ei", "एइ"], ["ai", "आइ"], ["au", "आउ"], ["oi", "ओइ"], ["iu", "ईउ"], ["ui", "ूई"],
    ["á", "आ"], ["â", "अ"], ["à", "आ"], ["é", "ए"], ["ê", "ए"], ["í", "ई"], ["ó", "ओ"], ["ô", "ओ"], ["ú", "ऊ"],
    ["a", "आ"], ["e", "ए"], ["i", "ई"], ["o", "ओ"], ["u", "उ"],
    ["b", "ब्"], ["c", "क्"], ["ç", "स्"], ["d", "द्"], ["f", "फ़्"], ["g", "ग्"], ["h", ""], ["j", "झ़्"], ["k", "क्"], ["l", "ल्"], ["m", "म्"], ["n", "न्"], ["p", "प्"], ["q", "क्"], ["r", "र्"], ["s", "स्"], ["t", "त्"], ["v", "व्"], ["w", "व्"], ["y", "य्"], ["z", "ज़्"]
